import{d as r,C as s,o as g,c as h,a3 as t,E as e,j as a,a as d}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十九章","description":"《正易心法》第二十九章——爻数三百八十又四，以闰求之，其数吻合：384 爻是真天文数，汉儒「六日七分」「除四卦」皆附会；以闰求之则无余欠，三年乾坤气数始足。","frontmatter":{"title":"正易心法·第二十九章","description":"《正易心法》第二十九章——爻数三百八十又四，以闰求之，其数吻合：384 爻是真天文数，汉儒「六日七分」「除四卦」皆附会；以闰求之则无余欠，三年乾坤气数始足。","category":"guide","aliases":["正易心法第二十九章","爻数三百八十四","以闰求之"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-29.md","filePath":"yijing/zheng-yi-xin-fa/chapter-29.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-29.md"},f=r({...c,setup(u){const i=[{id:"z29-01",label:"一、爻数三百八十四",showLabel:!0,sentences:[["爻数三百八十又四，以",{text:"闰",glossary:"run"},"求之，其数吻合。"]],note:["六十四卦的爻数共三百八十四，用闰月来推算，其数自然吻合。（**384 的来源很简单**：64 卦 × 6 爻 = 384 爻。**麻衣要问的是：这个数在天文历法上有没有对应？** 这是汉代以来易学家反复追问的问题。）"]},{id:"z29-02",label:"二、真天文也",showLabel:!0,sentences:[["爻数三百八十又四，",{text:"真天文",glossary:"zhenTianwen"},"也。诸儒求合其数而不可得。"]],note:["爻数三百八十四，是真正的天文之数；历代儒者想要找到与这个数相合的天文依据，却始终找不到。（**「真天文也」四个字是本章的判断前提**：麻衣认为 384 不是偶然的数字游戏，而是天文实数的映现——**问题不在数字，在找法。**）"]},{id:"z29-03",label:"三、汉儒二说皆附会",showLabel:!0,sentences:[["或谓一卦",{text:"六曰七分",glossary:"liuriQifen"},"，或谓除震离坎兑之数，皆",{text:"附会",glossary:"fuhui"},"也。"]],note:["有人说一卦对应「六日七分」，有人说要去掉震离坎兑四卦的爻数（用三百六十爻对应周天三百六十度）——这些都是牵强附会。（**汉儒两法都是「先有结论再凑数」**：前者用 60 卦配 360 天；后者人为剪裁掉四正卦的 24 爻。**麻衣的标准很清楚：如果需要删改数据，那就是附会。**）"]},{id:"z29-04",label:"四、以闰求之无余欠",showLabel:!0,sentences:[["倘以闰求之，则三百八十四数，自然吻合，无余欠矣。盖天度或",{text:"嬴缩",glossary:"yingsuo"},"，至三年，乾坤之气数始足于此也。"]],note:["如果用闰月来推算，那么三百八十四这个数自然吻合，没有多余也没有亏欠。原因在于天体运行有时盈余有时亏缺，到了三年，乾坤的气数才在这里完整足备。（**算法大致是**：太阴历一年约 354 天，太阳历一年约 365 天，年差约 11 天，三年累积约 33 天——正好添一个闰月。**含闰的阴历年因此约 384 天，与 384 爻相应。** 麻衣用「或嬴或缩」解释天度的不均匀，**「至三年，乾坤气数始足」则把这个吻合从「某一年」扩大到了「一个完整周期」。**）"]},{id:"z29-05",label:"五、惟真人得其说",showLabel:!0,sentences:[["由汉以来不悟，惟真人得其说。"]],note:["从汉代以来没有人领悟这个道理，只有真人（麻衣）得到了这个解释。（**这是《正易心法》中罕见的一句「自我宣称」**——前二十八章麻衣几乎从不说「只有我懂」，只批评错误。**但这一章他说「惟真人得其说」**：这句话值得停下来想想。一个人说「只有我懂」，可能是**真的懂了**，也可能是**「以为自己懂了」**。**麻衣的分量在于：他不是标榜，而是指出了一个方向，并且这个方向是可验证的**——三年一闰是历法常识，384 与含闰阴历年的吻合，读者可以自己算。）"]}],l=[{id:"run",term:"闰",pinyin:"rùn",meaning:"闰月、闰年。农历以闰月调整阴阳历差，三年一闰。"},{id:"zhenTianwen",term:"真天文",pinyin:"zhēn tiān wén",meaning:"真正的天文历法之数。麻衣认为 384 是真实的天文数据，非偶然。"},{id:"liuriQifen",term:"六曰七分",pinyin:"liù rì qī fēn",meaning:"汉代卦气说的一种算法：一卦配六日七分（约 6.875 天）。「曰」通「日」。"},{id:"fuhui",term:"附会",pinyin:"fù huì",meaning:"牵强凑合。麻衣批评汉儒：先有结论，再凑数字。"},{id:"yingsuo",term:"嬴缩",pinyin:"yíng suō",meaning:"盈余与亏缺。天度有时多出（嬴）有时不足（缩）——太阳视运动不均匀。"}];return(b,n)=>{const o=s("DaoTextReading"),p=s("DaoKeywordCards");return g(),h("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第二十九章" tabindex="-1">正易心法·第二十九章 <a class="header-anchor" href="#正易心法·第二十九章" aria-label="Permalink to &quot;正易心法·第二十九章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章的核心命题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>384 爻是真天文数</span></span>
<span class="line"><span>对应一个含闰月的完整阴历年（约 384 天）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>批评汉儒：</span></span>
<span class="line"><span>  「六日七分」说 = 附会</span></span>
<span class="line"><span>  「除四正卦」说 = 附会</span></span>
<span class="line"><span>  两者都是强行凑数，非自然之理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣的解法：以闰求之</span></span>
<span class="line"><span>  阴历闰年 = 354 + 30 = 384 天</span></span>
<span class="line"><span>  = 384 爻，无余欠，自然吻合</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结论：三年乾坤气数始足</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>汉代两种「附会」方案</strong>：</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>麻衣的判断</th></tr></thead><tbody><tr><td>一卦六日七分</td><td>用 60 卦（去四正卦）配 360 天，360÷60＝6，再加零头</td><td>先有结论（想配日）再凑数字</td></tr><tr><td>除震离坎兑之数</td><td>去掉四正卦的 24 爻，384−24＝360，配周天 360 度</td><td>为什么偏偏去掉这四卦？人为剪裁</td></tr></tbody></table><p><strong>麻衣的解法——「以闰求之」</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>太阳历：一年 = 365.25 天</span></span>
<span class="line"><span>太阴历：一年 = 354 天（12 个月 × 29.5 天）</span></span>
<span class="line"><span>年差：365.25 − 354 ≈ 11.25 天</span></span>
<span class="line"><span>三年累积：≈ 33.75 天 ≈ 一个闰月</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阴历三年 = 37 个月（12+12+13）</span></span>
<span class="line"><span>37 × 29.5 ≈ 1091.5 天 ÷ 3 ≈ 363.8 天</span></span>
<span class="line"><span></span></span>
<span class="line"><span>含闰的阴历年 ≈ 384 天 = 384 爻</span></span></code></pre></div><p><strong>「天度或嬴或缩」</strong>：太阳在近日点（冬至前后）运行快，远日点（夏至前后）运行慢；月亮在近地点快、远地点慢——<strong>农历用闰月来调整这种「嬴缩」，三年一个完整的气数周期。</strong></p><p><strong>「以人合天」vs「以天证易」——两条路的分别</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>汉儒（以人合天）：先有卦（人的符号系统），再去找天文数据来配合 → 附会</span></span>
<span class="line"><span>麻衣（以天证易）：先看天文的真实规律（闰月），再发现卦数与天文的自然吻合 → 吻合</span></span></code></pre></div><p><strong>这正是全书的核心立场</strong>：《易》不是人造的符号系统，是宇宙自然规律的呈现。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把 384 的来历记住：<strong>64 × 6 = 384</strong>；</li><li>再看汉儒两法错在哪：<strong>都是「先有结论再凑数」</strong>；</li><li>最后看麻衣的方法：<strong>从历法的真实规律出发，看它是否自然吻合。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>384 爻</strong>：六十四卦的爻数。</li><li><strong>真天文</strong>：麻衣判断它是天文实数。</li><li><strong>汉儒二说</strong>：六日七分、除四卦——皆附会。</li><li><strong>以闰求之</strong>：含闰阴历年约 384 天。</li><li><strong>嬴缩</strong>：天度有嬴有缩，三年气数始足。</li><li><strong>以天证易</strong>：不是凑合，是吻合。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,18)),e(o,{colophon:"三百八十四爻 · 真天文 · 以闰求之 · 无余欠",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十九章原文",sections:i,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「一卦六曰七分」之「曰」通「日」（六日七分），此处依底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[d("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"真天文",pinyin:["zhēn","tiān"],meaning:"麻衣的判断前提：384 爻不是偶然的数字，而是天文实数的映现——问题不在数字，在找法。"},{term:"六日七分",pinyin:["liù","rì"],meaning:"汉代卦气说：60 卦配 360 天，一卦约六日七分。麻衣判为「附会」。"},{term:"除四卦之数",pinyin:["chú","sì"],meaning:"去掉震离坎兑（四正卦）的 24 爻，得 360 爻配周天——麻衣同样判为附会。"},{term:"以闰求之",pinyin:["yǐ","rùn"],meaning:"含闰的阴历年约 384 天＝384 爻。不是凑合，是自然吻合，故「无余欠」。"},{term:"以天证易",pinyin:["yǐ","tiān"],meaning:"先看天文真实规律，再发现卦数与它的自然吻合——与汉儒「以人合天」（先定结论再凑数）相反。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章的核心命题：<strong>384 爻是真天文数，对应一个含闰月的完整阴历年（约 384 天）。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>汉儒两法都是附会：</span></span>
<span class="line"><span>  ① 一卦六日七分（60 卦配 360 天）</span></span>
<span class="line"><span>  ② 除震离坎兑之数（384−24＝360）</span></span>
<span class="line"><span>麻衣的解法：以闰求之 → 自然吻合，无余欠</span></span>
<span class="line"><span>结论：三年乾坤气数始足</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>汉儒为什么找不到？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>汉儒的思路：用一年（365 天）去除以 64 卦 → 凑不出整数 → 附会</span></span>
<span class="line"><span>麻衣的思路：不用阳历年（365 天），用阴历闰年（约 384 天）→ 完全吻合</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关键差异：汉儒以阳历为标准；麻衣以阴阳合历为标准</span></span>
<span class="line"><span>为什么阴历更合适？《易》的核心是阴阳，阴历本身就是阴阳（日月）合历</span></span></code></pre></div><p><strong>「以人合天」vs「以天证易」</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以人合天 → 附会（先定结论，再凑数字）</span></span>
<span class="line"><span>以天证易 → 吻合（先看天文，再看卦数）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这正是全书的核心立场：</span></span>
<span class="line"><span>  《易》不是人造的符号系统，是宇宙自然规律的呈现</span></span>
<span class="line"><span>  = 「此象之自然，有不可得而容心者」（第二十八章）</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>记住 384 的来历（64×6），以及它与含闰阴历年的关系；</li><li>再看两条路的分别：<strong>「以人合天」与「以天证易」</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>麻衣批评汉儒「附会」，那么麻衣的「以闰求之」是不是另一种更精巧的附会？</strong> 我的看法：<strong>它比汉儒高一层，但边界仍然是模糊的。</strong> 差别在于：<strong>汉儒删改了数据，麻衣没有。</strong> 但「384 与含闰阴历年吻合」这件事——<strong>闰年在实际历法中并不固定（有时 383 天、有时 385 天），这个「吻合」有多精确，是可以追问的。</strong> 我倾向于这样看：<strong>麻衣做的是「找出一个吻合」，而不是「证明唯一吻合」。</strong> 这在象数之学里是常态：<strong>不是「唯一解」，是「有一个自然的落处」。</strong> 而「有没有自然落处」，正是麻衣与汉儒的分野——<strong>不是精确度之争，是方向之争。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六十四卦的爻数共三百八十四，用闰月来推算，其数自然吻合。</p><p>爻数三百八十四，是真正的天文之数；历代儒者想要找到与这个数相合的天文依据，却始终找不到。</p><p>有人说一卦对应「六日七分」，有人说要去掉震离坎兑四卦的爻数——这些都是牵强附会。</p><p>如果用闰月来推算，那么三百八十四这个数自然吻合，没有多余也没有亏欠。原因在于天体运行有时盈余有时亏缺，到了三年，乾坤的气数才在这里完整足备。</p><p>从汉代以来没有人领悟这个道理，只有真人（麻衣）得到了这个解释。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十九章是一次「换框架」——<strong>汉儒在阳历里凑不出 384，麻衣换成了含闰的阴历，数字自己就站住了。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「真天文也」</strong>——这是麻衣的前提，也是他最坚决的地方：<strong>384 不是数字游戏，是真实的天文数。</strong> 问题不在数字，在<strong>找法</strong>。</li><li><strong>汉儒两法错在哪</strong>——都是「先有结论，再凑数」。<strong>一个要删掉四正卦，一个用 60 卦配 360 天。</strong> 麻衣的标准很清楚：<strong>要删改数据，就是附会。</strong></li><li><strong>「以闰求之」</strong>——换框架这一步很关键：<strong>汉儒用阳历（365 天），麻衣用阴阳合历（含闰约 384 天）。</strong> 而《易》的核心是阴阳，<strong>用阴阳合历来解《易》，比用纯阳历更贴合《易》的本质。</strong></li><li><strong>「三年，乾坤之气数始足」</strong>——这句话把「384」从「一年的天数」改成了「<strong>三年一个完整周期的天数</strong>」。<strong>这很重要：不是一个点上的吻合，是一个周期上的吻合。</strong></li><li><strong>「惟真人得其说」</strong>——这是全书少见的自我宣称。<strong>前二十八章他都在批评别人，这一章他说「只有我懂」。</strong> 我的看法是：<strong>这句话有风险，但麻衣敢说，是因为他给出了可验证的方法</strong>——读者可以自己去算。<strong>一个「只有我懂」如果是可验证的，它就不是标榜；如果不可验证，它就是标榜。</strong> 麻衣这一句，属于前者。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>麻衣批评汉儒「附会」，那他的「以闰求之」是不是另一种更精巧的附会？</strong> 我的看法：<strong>它高一层，但边界仍模糊。</strong> 差别是：<strong>汉儒删改了数据，麻衣没有。</strong> 但闰年在实际历法里并不固定（383～385 天），<strong>这个「吻合」的精度，是可以追问的。</strong> 我更愿意这样看：<strong>麻衣做的是「找出一个自然的落处」，不是「证明唯一解」。</strong> 而「有没有自然落处」，正是他与汉儒的分野——<strong>不是精确度之争，是方向之争。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-28">第二十八章 · 乾坤六子</a> — 「不可得而容心」（本章的「非附会」是其延伸）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-30">第三十章 · 画纯为叠</a> — 384＝360＋24（本章的内部推导）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-31">第三十一章</a> — 八宫八变与一年之数</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「大衍之数五十」：筮法的数理背景</li></ul>`,23))])}}});export{y as __pageData,f as default};
